import json, re, chess

def run_solution(fen):
    for pattern, repl in json.load(open("/app/re.json")):
        fen = re.sub(pattern, repl, fen)
    return fen

def check(fen, verbose=True):
    out = run_solution(fen)
    our = [" ".join(x.split(" ")[:-2]) for x in out.split("\n") if x.strip()!=""]
    b = chess.Board(fen)
    exp = set()
    for m in b.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN:
            continue
        c = b.copy(); c.push(m)
        exp.add(" ".join(c.fen().split(" ")[:-2]))
    ok = True
    bad = []
    for x in our:
        if not (x in exp or x.rpartition(" ")[0]+" -" in exp):
            ok = False; bad.append(x)
    missing = exp - set(our) - {x.rpartition(" ")[0]+" -" for x in our}
    if verbose:
        print(f"fen={fen}")
        print(f"  our={len(our)} exp={len(exp)} match_count={len(our)==len(exp)} all_ours_valid={ok}")
        if bad: print("  BAD:", bad[:5])
        if missing: print("  MISSING:", list(missing)[:5])
    return ok and len(our)==len(exp) and not bad

