import json, re, chess, random, sys

SOL = json.load(open("/app/re.json"))
def run_solution(fen):
    for pattern, repl in SOL:
        fen = re.sub(pattern, repl, fen)
    return [" ".join(x.split(" ")[:-2]) for x in fen.split("\n") if x.strip()!=""]

def expected(fen):
    b = chess.Board(fen)
    s = set()
    for m in b.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN:
            continue
        c = b.copy(); c.push(m)
        s.add(" ".join(c.fen().split(" ")[:-2]))
    return s

def check(fen, quiet=False):
    our = run_solution(fen)
    exp = expected(fen)
    ok = True; bad=[]; missing=set()
    for x in our:
        if not (x in exp or x.rpartition(" ")[0]+" -" in exp):
            ok=False; bad.append(x)
    our_norm = set(our) | {x.rpartition(" ")[0]+" -" for x in our}
    missing = exp - our_norm
    if len(our)!=len(exp) or bad or missing:
        ok=False
    if not ok or not quiet:
        print(f"{'OK ' if ok else 'FAIL'} fen={fen} our={len(our)} exp={len(exp)} bad={bad[:3]} missing={list(missing)[:3]}")
    return ok

